//! Client for the Pangram API (<https://docs.pangram.com/api-reference/>).
//!
//! Pangram exposes three hosts:
//!
//! * `https://text.external-api.pangram.com`: model discovery, async AI
//!   detection tasks, and bulk jobs. Generated by progenitor from
//!   `spec/pangram-text.json` into the [`text`] module (see
//!   `cargo xtask generate`).
//! * `https://plagiarism.api.pangram.com`: synchronous plagiarism checks.
//!   Generated from `spec/pangram-plagiarism.json` into [`plagiarism`].
//! * `https://file-external.api.pangram.com`: multipart file uploads.
//!   Hand-written in [`upload`] and [`Pangram::upload_files`], because
//!   progenitor does not generate `multipart/form-data` requests.
//!
//! [`Pangram`] wraps all three behind one API key, records every exchange in
//! a [`history::History`], and offers blocking-style helpers that poll async
//! tasks and bulk jobs to completion.

pub mod error;
pub mod history;
pub mod upload;

mod generated;
pub use generated::{plagiarism, text};

use std::collections::BTreeMap;
use std::sync::{Arc, Mutex};
use std::time::{Duration, Instant};

use progenitor_client::{ClientInfo, ResponseValue};
use serde::Serialize;

pub use error::{Error, Result};
pub use history::{Entry, History};
pub use plagiarism::types::{PlagiarismRequest, PlagiarismResult, PlagiarizedContent};
pub use text::types::{
    BulkCreated, BulkItem, BulkItemsPage, BulkRequest, BulkRequestItem, BulkResultItem,
    BulkResultsPage, BulkStatus, ModelsResponse, TaskCreated, TaskRequest, TaskStatus, Window,
};
pub use upload::{FileUploadResult, UploadFile};

pub const TEXT_BASE_URL: &str = "https://text.external-api.pangram.com";
pub const PLAGIARISM_BASE_URL: &str = "https://plagiarism.api.pangram.com";
pub const FILE_UPLOAD_BASE_URL: &str = "https://file-external.api.pangram.com";

/// The header carrying the API key.
pub const API_KEY_HEADER: &str = "x-api-key";

/// The model selector that follows Pangram's current default model.
pub const DEFAULT_MODEL: &str = "default";

/// Known values of [`TaskStatus::stage`].
pub mod stage {
    pub const SUCCESS: &str = "STAGE_SUCCESS";
    pub const FAILED: &str = "STAGE_FAILED";

    /// Whether a stage is terminal (the task will not change again).
    pub fn is_terminal(stage: &str) -> bool {
        stage == SUCCESS || stage == FAILED
    }
}

/// Known values of [`BulkStatus::status`].
pub mod bulk_status {
    pub const QUEUED: &str = "queued";
    pub const RUNNING: &str = "running";
    pub const SUCCEEDED: &str = "succeeded";
    pub const FAILED: &str = "failed";
    pub const PARTIAL: &str = "partial";

    /// Whether a status is terminal.
    pub fn is_terminal(status: &str) -> bool {
        matches!(status, SUCCEEDED | FAILED | PARTIAL)
    }
}

/// Known values of [`Window::label`] for Pangram 4.
pub mod label {
    pub const AI_GENERATED: &str = "AI-Generated";
    pub const AI_ASSISTED: &str = "AI-Assisted";
    pub const HUMAN_WRITTEN: &str = "Human Written";
}

impl TaskStatus {
    pub fn is_terminal(&self) -> bool {
        stage::is_terminal(&self.stage)
    }

    pub fn is_success(&self) -> bool {
        self.stage == stage::SUCCESS
    }

    pub fn is_failed(&self) -> bool {
        self.stage == stage::FAILED
    }
}

impl BulkStatus {
    pub fn is_terminal(&self) -> bool {
        bulk_status::is_terminal(&self.status)
    }
}

/// How to poll an async task or bulk job.
#[derive(Debug, Clone)]
pub struct PollOptions {
    /// Delay between status requests.
    pub interval: Duration,
    /// Give up after this long; `None` waits forever.
    pub timeout: Option<Duration>,
}

impl Default for PollOptions {
    fn default() -> Self {
        Self {
            interval: Duration::from_secs(2),
            timeout: None,
        }
    }
}

/// Connection settings for [`Pangram`].
#[derive(Debug, Clone)]
pub struct Config {
    pub api_key: String,
    pub text_base_url: String,
    pub plagiarism_base_url: String,
    pub file_upload_base_url: String,
    /// Per-request timeout for the underlying HTTP client.
    pub request_timeout: Duration,
}

impl Config {
    pub fn new(api_key: impl Into<String>) -> Self {
        Self {
            api_key: api_key.into(),
            text_base_url: TEXT_BASE_URL.to_string(),
            plagiarism_base_url: PLAGIARISM_BASE_URL.to_string(),
            file_upload_base_url: FILE_UPLOAD_BASE_URL.to_string(),
            request_timeout: Duration::from_secs(120),
        }
    }
}

/// A client for all Pangram APIs sharing one API key.
///
/// Every call is appended to an internal [`History`] that can be read with
/// [`Pangram::history`].
#[derive(Clone)]
pub struct Pangram {
    http: reqwest::Client,
    text: text::Client,
    plagiarism: plagiarism::Client,
    file_upload_base_url: String,
    history: Arc<Mutex<History>>,
}

impl std::fmt::Debug for Pangram {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.debug_struct("Pangram")
            .field("text_base_url", &self.text.baseurl())
            .field("plagiarism_base_url", &self.plagiarism.baseurl())
            .field("file_upload_base_url", &self.file_upload_base_url)
            .finish_non_exhaustive()
    }
}

impl Pangram {
    /// Builds a client that sends the configured API key with every request.
    pub fn new(config: Config) -> Result<Self> {
        let mut headers = reqwest::header::HeaderMap::new();
        let mut key = reqwest::header::HeaderValue::from_str(&config.api_key)
            .map_err(|e| Error::InvalidRequest(format!("invalid API key: {e}")))?;
        key.set_sensitive(true);
        headers.insert(API_KEY_HEADER, key);

        let http = reqwest::Client::builder()
            .default_headers(headers)
            .timeout(config.request_timeout)
            .user_agent(concat!(
                env!("CARGO_PKG_NAME"),
                "/",
                env!("CARGO_PKG_VERSION")
            ))
            .build()?;

        Ok(Self {
            text: text::Client::new_with_client(trim_slash(&config.text_base_url), http.clone()),
            plagiarism: plagiarism::Client::new_with_client(
                trim_slash(&config.plagiarism_base_url),
                http.clone(),
            ),
            file_upload_base_url: trim_slash(&config.file_upload_base_url).to_string(),
            http,
            history: Arc::new(Mutex::new(History::default())),
        })
    }

    /// Builds a client from `api_key` with default base URLs.
    pub fn with_api_key(api_key: impl Into<String>) -> Result<Self> {
        Self::new(Config::new(api_key))
    }

    /// The generated text API client, for operations not wrapped here.
    pub fn text(&self) -> &text::Client {
        &self.text
    }

    /// The generated plagiarism API client.
    pub fn plagiarism(&self) -> &plagiarism::Client {
        &self.plagiarism
    }

    /// A snapshot of every exchange made so far.
    pub fn history(&self) -> History {
        self.history.lock().expect("history mutex poisoned").clone()
    }

    /// Removes and returns all recorded exchanges.
    pub fn take_history(&self) -> History {
        std::mem::take(&mut *self.history.lock().expect("history mutex poisoned"))
    }

    fn text_url(&self, path: &str) -> String {
        format!("{}{}", self.text.baseurl(), path)
    }

    // ----- models ---------------------------------------------------------

    /// `GET /models`
    pub async fn list_models(&self) -> Result<ModelsResponse> {
        let url = self.text_url("/models");
        let result = self.text.list_models().await;
        self.finish("GET", url, None, result).await
    }

    // ----- tasks ----------------------------------------------------------

    /// `POST /task`
    pub async fn create_task(&self, request: &TaskRequest) -> Result<TaskCreated> {
        let url = self.text_url("/task");
        let body = serde_json::to_value(request).ok();
        let result = self.text.create_task(request).await;
        self.finish("POST", url, body, result).await
    }

    /// `GET /task/{task_id}`
    pub async fn get_task(&self, task_id: &str) -> Result<TaskStatus> {
        let url = self.text_url(&format!("/task/{}", encode_path(task_id)));
        let result = self.text.get_task(task_id).await;
        self.finish("GET", url, None, result).await
    }

    /// Polls `GET /task/{task_id}` until the stage is terminal.
    ///
    /// A task that ends in `STAGE_FAILED` is returned as `Ok`; check
    /// [`TaskStatus::is_failed`].
    pub async fn wait_for_task(&self, task_id: &str, poll: &PollOptions) -> Result<TaskStatus> {
        let started = Instant::now();
        loop {
            let status = self.get_task(task_id).await?;
            if status.is_terminal() {
                return Ok(status);
            }
            tracing::debug!(task_id, stage = %status.stage, "task not terminal yet");
            self.sleep_or_timeout(started, poll, || format!("task {task_id}"))
                .await?;
        }
    }

    /// `POST /task` followed by polling until terminal.
    pub async fn detect(&self, request: &TaskRequest, poll: &PollOptions) -> Result<TaskStatus> {
        let created = self.create_task(request).await?;
        self.wait_for_task(&created.task_id, poll).await
    }

    // ----- bulk -----------------------------------------------------------

    /// `POST /bulk`
    pub async fn create_bulk(&self, request: &BulkRequest) -> Result<BulkCreated> {
        let url = self.text_url("/bulk");
        let body = serde_json::to_value(request).ok();
        let result = self.text.create_bulk(request).await;
        self.finish("POST", url, body, result).await
    }

    /// `GET /bulk/{bulk_id}`
    pub async fn get_bulk(&self, bulk_id: &str) -> Result<BulkStatus> {
        let url = self.text_url(&format!("/bulk/{}", encode_path(bulk_id)));
        let result = self.text.get_bulk(bulk_id).await;
        self.finish("GET", url, None, result).await
    }

    /// `GET /bulk/{bulk_id}/items`
    pub async fn list_bulk_items(
        &self,
        bulk_id: &str,
        offset: Option<u32>,
        limit: Option<u32>,
    ) -> Result<BulkItemsPage> {
        let url = self.text_url(&format!(
            "/bulk/{}/items{}",
            encode_path(bulk_id),
            page_query(offset, limit)
        ));
        let limit = nonzero(limit)?;
        let result = self.text.list_bulk_items(bulk_id, limit, offset).await;
        self.finish("GET", url, None, result).await
    }

    /// `GET /bulk/{bulk_id}/results`
    pub async fn list_bulk_results(
        &self,
        bulk_id: &str,
        offset: Option<u32>,
        limit: Option<u32>,
    ) -> Result<BulkResultsPage> {
        let url = self.text_url(&format!(
            "/bulk/{}/results{}",
            encode_path(bulk_id),
            page_query(offset, limit)
        ));
        let limit = nonzero(limit)?;
        let result = self.text.list_bulk_results(bulk_id, limit, offset).await;
        self.finish("GET", url, None, result).await
    }

    /// Pages through `GET /bulk/{bulk_id}/results` and concatenates every
    /// page into one. The returned page has `offset` 0 and `limit` equal to
    /// the number of items fetched.
    pub async fn all_bulk_results(&self, bulk_id: &str) -> Result<BulkResultsPage> {
        const PAGE: u32 = 1000;
        let mut offset = 0u32;
        let mut combined: Option<BulkResultsPage> = None;
        loop {
            let page = self
                .list_bulk_results(bulk_id, Some(offset), Some(PAGE))
                .await?;
            let fetched = (page.items.len() + page.failed_items.len()) as u32;
            let total = page.total_items;
            match combined.as_mut() {
                None => combined = Some(page),
                Some(c) => {
                    c.items.extend(page.items);
                    c.failed_items.extend(page.failed_items);
                }
            }
            offset += fetched;
            if fetched == 0 || offset >= total {
                break;
            }
        }
        let mut combined = combined.expect("loop ran at least once");
        combined.offset = 0;
        combined.limit = (combined.items.len() + combined.failed_items.len()) as u32;
        Ok(combined)
    }

    /// Polls `GET /bulk/{bulk_id}` until the status is terminal.
    pub async fn wait_for_bulk(&self, bulk_id: &str, poll: &PollOptions) -> Result<BulkStatus> {
        let started = Instant::now();
        loop {
            let status = self.get_bulk(bulk_id).await?;
            if status.is_terminal() {
                return Ok(status);
            }
            tracing::debug!(bulk_id, status = %status.status, "bulk job not terminal yet");
            self.sleep_or_timeout(started, poll, || format!("bulk job {bulk_id}"))
                .await?;
        }
    }

    // ----- plagiarism -----------------------------------------------------

    /// `POST /` on the plagiarism host.
    pub async fn check_plagiarism(&self, text: impl Into<String>) -> Result<PlagiarismResult> {
        let request = PlagiarismRequest { text: text.into() };
        let url = format!("{}/", self.plagiarism.baseurl());
        let body = serde_json::to_value(&request).ok();
        let result = self.plagiarism.check_plagiarism(&request).await;
        self.finish("POST", url, body, result).await
    }

    // ----- file upload ----------------------------------------------------

    /// `POST /` on the file upload host, as `multipart/form-data`.
    pub async fn upload_files(
        &self,
        files: Vec<UploadFile>,
        public_dashboard_link: bool,
    ) -> Result<Vec<FileUploadResult>> {
        if files.is_empty() {
            return Err(Error::InvalidRequest("no files to upload".into()));
        }
        let url = format!("{}/", self.file_upload_base_url);
        let described = serde_json::json!({
            "files": files.iter().map(|f| f.file_name.clone()).collect::<Vec<_>>(),
            "public_dashboard_link": public_dashboard_link,
        });

        let mut form = reqwest::multipart::Form::new()
            .text("public_dashboard_link", public_dashboard_link.to_string());
        for file in files {
            let part = reqwest::multipart::Part::bytes(file.bytes).file_name(file.file_name);
            form = form.part("files", part);
        }

        let sent = self.http.post(&url).multipart(form).send().await;
        let response = match sent {
            Ok(r) => r,
            Err(e) => {
                self.record_failure("POST", url, Some(described), &e);
                return Err(e.into());
            }
        };
        let status = response.status();
        let headers = history::headers_to_map(response.headers());
        let bytes = response.bytes().await?;
        let body = bytes_to_value(&bytes);
        self.record(Entry {
            timestamp: history::now(),
            request_url: url.clone(),
            verb: "POST".into(),
            request_body: Some(described),
            status: Some(status.as_u16()),
            response_body: body.clone(),
            response_headers: headers.clone(),
            error: None,
        });
        if !status.is_success() {
            return Err(Error::Api {
                verb: "POST".into(),
                url,
                status: status.as_u16(),
                headers,
                body,
            });
        }
        serde_json::from_value(body).map_err(|e| Error::InvalidResponse {
            url,
            message: e.to_string(),
        })
    }

    // ----- internals ------------------------------------------------------

    async fn sleep_or_timeout(
        &self,
        started: Instant,
        poll: &PollOptions,
        what: impl FnOnce() -> String,
    ) -> Result<()> {
        if let Some(timeout) = poll.timeout {
            if started.elapsed() + poll.interval > timeout {
                return Err(Error::Timeout(timeout, what()));
            }
        }
        tokio::time::sleep(poll.interval).await;
        Ok(())
    }

    fn record(&self, entry: Entry) {
        self.history
            .lock()
            .expect("history mutex poisoned")
            .push(entry);
    }

    fn record_failure(
        &self,
        verb: &str,
        url: String,
        request_body: Option<serde_json::Value>,
        error: &dyn std::fmt::Display,
    ) {
        self.record(Entry {
            timestamp: history::now(),
            request_url: url,
            verb: verb.into(),
            request_body,
            status: None,
            response_body: serde_json::Value::Null,
            response_headers: BTreeMap::new(),
            error: Some(error.to_string()),
        });
    }

    /// Records the exchange in the history and converts a progenitor result
    /// into this crate's [`Result`].
    async fn finish<T, E>(
        &self,
        verb: &str,
        url: String,
        request_body: Option<serde_json::Value>,
        result: std::result::Result<ResponseValue<T>, progenitor_client::Error<E>>,
    ) -> Result<T>
    where
        T: Serialize + serde::de::DeserializeOwned,
        E: Serialize + std::fmt::Debug,
    {
        use progenitor_client::Error as PError;

        match result {
            Ok(value) => {
                let status = value.status();
                let headers = history::headers_to_map(value.headers());
                let inner = value.into_inner();
                self.record(Entry {
                    timestamp: history::now(),
                    request_url: url,
                    verb: verb.into(),
                    request_body,
                    status: Some(status.as_u16()),
                    response_body: serde_json::to_value(&inner).unwrap_or(serde_json::Value::Null),
                    response_headers: headers,
                    error: None,
                });
                Ok(inner)
            }
            Err(PError::ErrorResponse(value)) => {
                let status = value.status();
                let headers = history::headers_to_map(value.headers());
                let body =
                    serde_json::to_value(value.into_inner()).unwrap_or(serde_json::Value::Null);
                self.record(Entry {
                    timestamp: history::now(),
                    request_url: url.clone(),
                    verb: verb.into(),
                    request_body,
                    status: Some(status.as_u16()),
                    response_body: body.clone(),
                    response_headers: headers.clone(),
                    error: None,
                });
                Err(Error::Api {
                    verb: verb.into(),
                    url,
                    status: status.as_u16(),
                    headers,
                    body,
                })
            }
            Err(PError::UnexpectedResponse(response)) => {
                let status = response.status();
                let headers = history::headers_to_map(response.headers());
                let body = match response.bytes().await {
                    Ok(bytes) => bytes_to_value(&bytes),
                    Err(e) => serde_json::Value::String(format!("<unreadable body: {e}>")),
                };
                self.record(Entry {
                    timestamp: history::now(),
                    request_url: url.clone(),
                    verb: verb.into(),
                    request_body,
                    status: Some(status.as_u16()),
                    response_body: body.clone(),
                    response_headers: headers.clone(),
                    error: None,
                });
                if status.is_success() {
                    // A success status we did not model; try to decode it.
                    serde_json::from_value(body).map_err(|e| Error::InvalidResponse {
                        url,
                        message: e.to_string(),
                    })
                } else {
                    Err(Error::Api {
                        verb: verb.into(),
                        url,
                        status: status.as_u16(),
                        headers,
                        body,
                    })
                }
            }
            Err(PError::InvalidResponsePayload(bytes, e)) => {
                let body = bytes_to_value(&bytes);
                self.record(Entry {
                    timestamp: history::now(),
                    request_url: url.clone(),
                    verb: verb.into(),
                    request_body,
                    status: None,
                    response_body: body,
                    response_headers: BTreeMap::new(),
                    error: Some(format!("invalid response payload: {e}")),
                });
                Err(Error::InvalidResponse {
                    url,
                    message: e.to_string(),
                })
            }
            Err(PError::CommunicationError(e)) | Err(PError::InvalidUpgrade(e)) => {
                self.record_failure(verb, url, request_body, &e);
                Err(Error::Transport(e))
            }
            Err(PError::ResponseBodyError(e)) => {
                self.record_failure(verb, url.clone(), request_body, &e);
                Err(Error::InvalidResponse {
                    url,
                    message: e.to_string(),
                })
            }
            Err(PError::InvalidRequest(message)) => {
                self.record_failure(verb, url, request_body, &message);
                Err(Error::InvalidRequest(message))
            }
            Err(PError::Custom(message)) => {
                self.record_failure(verb, url, request_body, &message);
                Err(Error::InvalidRequest(message))
            }
        }
    }
}

fn nonzero(limit: Option<u32>) -> Result<Option<std::num::NonZeroU32>> {
    match limit {
        None => Ok(None),
        Some(0) => Err(Error::InvalidRequest("limit must be at least 1".into())),
        Some(n) => Ok(std::num::NonZeroU32::new(n)),
    }
}

fn trim_slash(url: &str) -> &str {
    url.trim_end_matches('/')
}

fn encode_path(segment: &str) -> String {
    progenitor_client::encode_path(segment)
}

fn page_query(offset: Option<u32>, limit: Option<u32>) -> String {
    let mut parts = Vec::new();
    if let Some(limit) = limit {
        parts.push(format!("limit={limit}"));
    }
    if let Some(offset) = offset {
        parts.push(format!("offset={offset}"));
    }
    if parts.is_empty() {
        String::new()
    } else {
        format!("?{}", parts.join("&"))
    }
}

/// Decodes a body as JSON, falling back to a string (or null when empty).
fn bytes_to_value(bytes: &[u8]) -> serde_json::Value {
    if bytes.is_empty() {
        return serde_json::Value::Null;
    }
    serde_json::from_slice(bytes)
        .unwrap_or_else(|_| serde_json::Value::String(String::from_utf8_lossy(bytes).into_owned()))
}
